1	/* Tier-2 C-level fixture: 16x16x16 GEMM via RVV intrinsics
2	 * (2-phase: QEMU1 -> vsim).
3	 *
4	 *   QEMU 1: init_matrices -- RVV vid.v + vadd.vx + vrem.vx fills A and B.
5	 *           V instructions retire just before the entry drain, exercising
6	 *           the plugin's HandoffSite translation-time PC capture (the
7	 *           old qemu_plugin_read_register("pc") path lagged for V).
8	 *   vsim:   vmatmul_kernel -- RVV outer-product GEMM (vle32 + vmacc.vx +
9	 *           vse32). C is written to .bss inside the ROI; the exit_vsim
10	 *           "memory" clobber anchors the stores so the kernel survives.
11	 *           vsim drains at the exit marker and exits 200.
12	 *
13	 * (The old phase-3 QEMU2 scalar re-verify was removed with the QEMU2 leg;
14	 * the fixture now validates that the RVV GEMM kernel runs and drains.)
15	 *
16	 * RVV shape
17	 *   VLEN=512, e32, LMUL=1 -> vlmax = 16 elements per V reg, exactly one
18	 *   row of a 16-wide matrix. The kernel runs N outer iterations (one per
19	 *   row of A), each accumulating into a single V register seeded to zero
20	 *   and storing it back as one row of C.
21	 *
22	 * Cross-phase memory survival (same convention as rt_c_matmul.c)
23	 *   Matrices sit in .bss. The "no redundant ELF reload" rule keeps phase-1
24	 *   .bss writes intact through the shared memory-backend-file.
25	 */
26	#include "runtime/rt_c_helpers.h"
27	
28	#include <riscv_vector.h>
29	#include <stdint.h>
30	
31	#define N 16
32	
33	static int32_t A[N * N];
34	static int32_t B[N * N];
35	static int32_t C[N * N];
36	
37	#define AT(M, i, j) ((M)[(i) *N + (j)])
38	
39	/* Vectorized init: one V register holds [0, 1, ..., N-1], reused across
40	 * rows. Per row i: A[i][:] = (vidx + i)   % 7, B[i][:] = (vidx + 3i) % 5.
41	 * vid.v writes unsigned lane indices; reinterpret to signed so the rest of
42	 * the math (and the int32_t* matrix pointers) stay in i32 land. */
43	static void init_matrices(void)
44	{
45	  size_t           vl     = __riscv_vsetvl_e32m1((size_t) N);
46	  const vuint32m1_t vidx_u = __riscv_vid_v_u32m1(vl);
47	  const vint32m1_t  vidx   = __riscv_vreinterpret_v_u32m1_i32m1(vidx_u);
48	
49	  for (int i = 0; i < N; i++) {
50	    vint32m1_t va = __riscv_vadd_vx_i32m1(vidx, i, vl);
51	    va            = __riscv_vrem_vx_i32m1(va, 7, vl);
52	    __riscv_vse32_v_i32m1(&AT(A, i, 0), va, vl);
53	
54	    vint32m1_t vb = __riscv_vadd_vx_i32m1(vidx, i * 3, vl);
55	    vb            = __riscv_vrem_vx_i32m1(vb, 5, vl);
56	    __riscv_vse32_v_i32m1(&AT(B, i, 0), vb, vl);
57	  }
58	}
59	
60	/* Outer-product RVV GEMM: for each row i of C, accumulate
61	 *   C[i][:] += A[i][k] * B[k][:]
62	 * using a single V register per row.
63	 *
64	 * noinline keeps the kernel a distinct symbol at -O1 so PC-range modes can
65	 * anchor on it, and keeps every kernel op inside the marker span (a call
66	 * cannot be reordered across the memory-clobbering enter/exit markers; see
67	 * runtime/rt_c_helpers.h cycle-attribution contract). */
68	static void __attribute__((noinline)) vmatmul_kernel(void)
69	{
70	  for (int i = 0; i < N; i++) {
71	    size_t     vl   = __riscv_vsetvl_e32m1((size_t) N);
72	    vint32m1_t vacc = __riscv_vmv_v_x_i32m1(0, vl);
73	    for (int k = 0; k < N; k++) {
74	      const int32_t  a_ik = AT(A, i, k);
75	      const vint32m1_t vb_k =
76	        __riscv_vle32_v_i32m1(&AT(B, k, 0), vl);
77	      vacc = __riscv_vmacc_vx_i32m1(vacc, a_ik, vb_k, vl);
78	    }
79	    __riscv_vse32_v_i32m1(&AT(C, i, 0), vacc, vl);
80	  }
81	}
82	
83	int main(void)
84	{
85	  /* Phase 1 (QEMU 1): seed inputs only. */
86	  init_matrices();
87	
88	#ifndef HYBRID_MARKERLESS
89	  enter_vsim();
90	#endif
91	
92	  /* Phase 2 (vsim): RVV kernel only. No I/O permitted. */
93	  vmatmul_kernel();
94	
95	#ifndef HYBRID_MARKERLESS
96	  exit_vsim();
97	#else
98	  /* No exit marker to anchor the C stores; force them live so the kernel
99	   * is not eliminated (the QEMU2 verify that read C was removed). */
100	  roi_anchor();
101	#endif
102	
103	  return 0;
104	}
